-- Fiche Le présent : verbes en -ir et verbes irréguliers (CE2) - conjugaison, notion 'present'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'ce2', 'conjugaison', 'Le présent : verbes en -ir et verbes irréguliers', $fiche$
[titre]Les verbes comme finir[/titre]
Beaucoup de verbes en [b]-ir[/b] se conjuguent comme [b]finir[/b] (2e groupe).
